PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,primary_email TEXT NOT NULL UNIQUE,email_verified INTEGER NOT NULL DEFAULT 0,display_name TEXT NOT NULL,legal_name TEXT,account_status TEXT NOT NULL CHECK(account_status IN('active','deactivated')),onboarding_status TEXT NOT NULL CHECK(onboarding_status IN('new','in_progress','pending','complete')),last_sign_in_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deactivated_at TEXT);
CREATE TABLE auth_identities(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),provider TEXT NOT NULL,provider_subject TEXT NOT NULL,provider_email TEXT NOT NULL,verified INTEGER NOT NULL,last_authenticated_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,provider_subject));
CREATE TABLE organizations(id TEXT PRIMARY KEY,organization_type TEXT NOT NULL,organization_number TEXT,legal_name TEXT,display_name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,program_year INTEGER,founding_organization_mode INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE organization_memberships(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),organization_id TEXT NOT NULL REFERENCES organizations(id),status TEXT NOT NULL CHECK(status IN('requested','pending','approved','suspended','deactivated','denied')),approved_at TEXT,deactivated_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,organization_id));
CREATE TABLE roles(id TEXT PRIMARY KEY,key TEXT NOT NULL UNIQUE,name TEXT NOT NULL,description TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE role_permissions(role_id TEXT NOT NULL REFERENCES roles(id),permission_key TEXT NOT NULL,PRIMARY KEY(role_id,permission_key));
CREATE TABLE membership_roles(id TEXT PRIMARY KEY,membership_id TEXT NOT NULL REFERENCES organization_memberships(id),role_id TEXT NOT NULL REFERENCES roles(id),active INTEGER NOT NULL DEFAULT 1,effective_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ends_at TEXT,assigned_by_user_id TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE households(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),display_name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('preliminary','active','inactive')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE household_members(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id),user_id TEXT NOT NULL REFERENCES users(id),relationship TEXT NOT NULL,primary_guardian INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(household_id,user_id));
CREATE TABLE dependents(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id),display_name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',fictional_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE access_requests(id TEXT PRIMARY KEY,requester_user_id TEXT NOT NULL REFERENCES users(id),organization_id TEXT NOT NULL REFERENCES organizations(id),proposed_household_id TEXT REFERENCES households(id),requested_relationship TEXT,reason TEXT,status TEXT NOT NULL CHECK(status IN('pending','approved','denied','correction_requested')),reviewed_by_user_id TEXT REFERENCES users(id),review_notes TEXT,reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invitations(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),email TEXT NOT NULL,intended_role_key TEXT,relationship TEXT,invited_by_user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN('pending','accepted','expired','revoked')),expires_at TEXT NOT NULL,accepted_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE onboarding_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),organization_id TEXT REFERENCES organizations(id),household_id TEXT REFERENCES households(id),current_step TEXT NOT NULL,state_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN('in_progress','submitted','complete','abandoned')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,status));
CREATE TABLE application_sessions(id_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,organization_id TEXT REFERENCES organizations(id),actor_user_id TEXT REFERENCES users(id),action TEXT NOT NULL,target_type TEXT,target_id TEXT,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_memberships_user_org ON organization_memberships(user_id,organization_id,status); CREATE INDEX idx_household_members_user ON household_members(user_id,active); CREATE INDEX idx_requests_org_status ON access_requests(organization_id,status); CREATE INDEX idx_audit_org_time ON audit_events(organization_id,created_at);
